using System.Runtime.InteropServices;
using System.Threading;
using System.Text.Json;
using System.Drawing;
using System.Drawing.Imaging;
using Dalamud.Bindings.ImGui;
using Dalamud.Interface.Textures;
using Dalamud.Interface.Textures.TextureWraps;
using Dalamud.Plugin.Services;
namespace OmniToolbox.LocalGlamourPreview;
// Only the SDK raw snapshot touches the game texture. Resize/JPEG use owned CPU bytes.
// No GPU scaling, WIC texture encoder, NVENC, or game-stream process is used here.
internal sealed class RemotePreviewFrames
{
 private readonly object gate=new();private long lease,next,currentRequest,frameRequest,serial;private int epoch;private bool busy;private CancellationTokenSource? operation;private string image="",error="";
 public string Read(string status){lock(gate){lease=Environment.TickCount64+2000;return JsonSerializer.Serialize(new{ok=true,requestId=frameRequest,serial,image,error,status=JsonSerializer.Deserialize<JsonElement>(status)});}}
 public void Reset(){lock(gate){epoch++;image="";error="";frameRequest=0;currentRequest=0;_=operation?.CancelAsync();}}
 public void Update(ITextureReadbackProvider reader,nint srv,int width,int height,long request,bool ready){lock(gate){if(request!=currentRequest){epoch++;currentRequest=request;image="";error="";frameRequest=0;_=operation?.CancelAsync();}long now=Environment.TickCount64;if(!ready||srv==0||busy||now>lease||now<next||width<1||height<1||width>4096||height>4096)return;var wrap=new RetainedSrv(srv,width,height);var cancellation=new CancellationTokenSource(TimeSpan.FromSeconds(2));operation=cancellation;busy=true;next=now+30;_=Capture(reader,wrap,request,epoch,cancellation);}}
 private async Task Capture(ITextureReadbackProvider reader,RetainedSrv wrap,long request,int ticket,CancellationTokenSource cancellation){try{byte[] encoded;using(wrap){var raw=await reader.GetRawImageAsync(wrap,new TextureModificationArgs{MakeOpaque=false,NewWidth=0,NewHeight=0},true,cancellation.Token).ConfigureAwait(false);wrap.Dispose();encoded=await Task.Run(()=>Encode(raw.Specification,raw.RawData,cancellation.Token),cancellation.Token).ConfigureAwait(false);}string data="data:image/jpeg;base64,"+Convert.ToBase64String(encoded);lock(gate)if(ticket==epoch&&request==currentRequest){image=data;frameRequest=request;error="";serial++;}}catch(OperationCanceledException){lock(gate)if(ticket==epoch)error="预览读回超时，正在重试";}catch(Exception e){lock(gate)if(ticket==epoch)error="预览读取失败："+e.Message;}finally{lock(gate){if(ReferenceEquals(operation,cancellation))operation=null;busy=false;}cancellation.Dispose();}}
 internal static byte[] Encode(RawImageSpecification spec,byte[] bytes,CancellationToken token){token.ThrowIfCancellationRequested();int width=spec.Width,height=spec.Height,pitch=spec.Pitch;int format=spec.DxgiFormat;if(width<1||height<1||width>4096||height>4096||pitch<width*4||pitch>32768||(long)pitch*height>bytes.Length)throw new InvalidDataException("预览像素尺寸无效");if(format is not (28 or 29 or 87 or 91 or 88 or 93))throw new InvalidDataException("预览像素格式暂不支持："+format);bool swap=format is 28 or 29;for(int y=0;y<height;y++){token.ThrowIfCancellationRequested();for(int x=0;x<width;x++){int i=y*pitch+x*4;if(swap)(bytes[i],bytes[i+2])=(bytes[i+2],bytes[i]);bytes[i+3]=255;}}var pin=GCHandle.Alloc(bytes,GCHandleType.Pinned);try{using var original=new Bitmap(width,height,pitch,PixelFormat.Format32bppArgb,pin.AddrOfPinnedObject());double scale=Math.Min(1,720d/height);using var output=new Bitmap(Math.Max(1,(int)(width*scale)),Math.Max(1,(int)(height*scale)),PixelFormat.Format24bppRgb);using(var graphics=Graphics.FromImage(output)){graphics.InterpolationMode=System.Drawing.Drawing2D.InterpolationMode.Bilinear;graphics.DrawImage(original,0,0,output.Width,output.Height);}token.ThrowIfCancellationRequested();using var stream=new MemoryStream();using var quality=new EncoderParameters(1);quality.Param[0]=new EncoderParameter(System.Drawing.Imaging.Encoder.Quality,68L);output.Save(stream,ImageCodecInfo.GetImageEncoders().First(x=>x.FormatID==ImageFormat.Jpeg.Guid),quality);if(stream.Length>512*1024)throw new InvalidDataException("预览帧过大");return stream.ToArray();}finally{pin.Free();}}
 private sealed class RetainedSrv:IDalamudTextureWrap{private nint pointer;public RetainedSrv(nint p,int w,int h){pointer=p;Width=w;Height=h;Marshal.AddRef(p);}public ImTextureID Handle=>new((ulong)pointer);public int Width{get;}public int Height{get;}public System.Numerics.Vector2 Size=>new(Width,Height);public IDalamudTextureWrap CreateWrapSharingLowLevelResource(){if(pointer==0)throw new ObjectDisposedException(nameof(RetainedSrv));return new RetainedSrv(pointer,Width,Height);}public void Dispose(){var p=Interlocked.Exchange(ref pointer,0);if(p!=0)Marshal.Release(p);}}
}
